const launch = Temporal.PlainDate.from("2027-01-01");
const earlier = launch.subtract({ months: 2 });

console.log(launch.toString());  // "2027-01-01" لم يتغيّر
console.log(earlier.toString()); // "2026-11-01" كائن جديد
console.log(launch.month);       // 1 — بلا طرح 1

const opening = Temporal.PlainTime.from("09:30:00");
const closing = opening.add({ hours: 8 });

console.log(closing.toString()); // "17:30:00"
console.log(opening.toString()); // "09:30:00" لم يتغيّر

const start = Temporal.PlainDate.from("2026-01-01");
const end = Temporal.PlainDate.from("2026-08-31");

const gap = start.until(end);
console.log(gap.toString()); // "P242D"

const inMonths = start.until(end, { largestUnit: "months" });
console.log(inMonths.months, "شهر و", inMonths.days, "يوم");

const meeting = Temporal.ZonedDateTime.from({
  year: 2026, month: 9, day: 10, hour: 14,
  timeZone: "Asia/Amman",
});

console.log(meeting.toString());
// "2026-09-10T14:00:00+03:00[Asia/Amman]"

const inTokyo = meeting.withTimeZone("Asia/Tokyo");
console.log(inTokyo.hour); // الساعة المقابلة فعليًا بطوكيو

class DbConnection {
